using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
public static class Native67WebPreviewExport {
 const string Root="Assets/Native67SpatialReview/";
 [Serializable]class Node {public string name;public int parent;public Vector3 position,scale;public Quaternion rotation;}
 [Serializable]class Clip {public string name,file;public float duration;public int frames;}
 [Serializable]class Report {public string status,error;public int vertices,triangles,skinNode;public Node[] nodes;public int[] joints;public Clip[] clips;public string guardScope="Authored Meshy boxing guard, retargeted Generic FK to native67. No invented pose; source curve file unchanged.";}
 static void FloatFile(string f,float[] a){var b=new byte[a.Length*4];Buffer.BlockCopy(a,0,b,0,b.Length);File.WriteAllBytes(f,b);}
 static void V3(string f,Vector3[] a){FloatFile(f,a.SelectMany(v=>new[]{v.x,v.y,v.z}).ToArray());}
 public static void Run(){string output=Environment.GetEnvironmentVariable("LF_NATIVE67_WEB_EXPORT");Directory.CreateDirectory(output);GameObject actor=null;Native67AlternativeDanceReview alt=null;var r=new Report();int exit=1;try{
 actor=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"SailorReview.fbx"));var skin=actor.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var mesh=skin.sharedMesh;var nodes=actor.GetComponentsInChildren<Transform>(true);r.nodes=nodes.Select(t=>new Node{name=t.name,parent=Array.IndexOf(nodes,t.parent),position=t.localPosition,rotation=t.localRotation,scale=t.localScale}).ToArray();r.skinNode=Array.IndexOf(nodes,skin.transform);r.joints=skin.bones.Select(t=>Array.IndexOf(nodes,t)).ToArray();if(r.joints.Any(i=>i<0))throw new Exception("Missing skin joint");r.vertices=mesh.vertexCount;r.triangles=mesh.triangles.Length/3;
 V3(output+"/positions.bin",mesh.vertices);V3(output+"/normals.bin",mesh.normals);FloatFile(output+"/tangents.bin",mesh.tangents.SelectMany(t=>new[]{t.x,t.y,t.z,t.w}).ToArray());FloatFile(output+"/uv.bin",mesh.uv.SelectMany(t=>new[]{t.x,t.y}).ToArray());var triangles=mesh.triangles;var bytes=new byte[triangles.Length*4];Buffer.BlockCopy(triangles,0,bytes,0,bytes.Length);File.WriteAllBytes(output+"/triangles.bin",bytes);
 var ids=SailorNative67SpatialImportReview.ReadSourceVertexIds(mesh,new SailorNative67SpatialImportReview.SourceIndexLayerContract{layerName="__LF_SOURCE_VERTEX_ID_V1",originalVertexCount=994452,denominator=1048576,originalUVLayerNames=new[]{"UVMap"},exportUVLayerOrder=new[]{"UVMap","__LF_SOURCE_VERTEX_ID_V1"},manifestCandidateChannel=1,verifiedImportedV=0});bytes=new byte[ids.Length*4];Buffer.BlockCopy(ids,0,bytes,0,bytes.Length);File.WriteAllBytes(output+"/originalIds.bin",bytes);FloatFile(output+"/bindposes.bin",mesh.bindposes.SelectMany(m=>Enumerable.Range(0,16).Select(i=>m[i%4,i/4])).ToArray());File.WriteAllLines(output+"/boneNames.txt",skin.bones.Select(t=>t.name));
 foreach(var a in actor.GetComponentsInChildren<Animator>(true))a.enabled=false;
 alt=new Native67AlternativeDanceReview(actor,skin);Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_GAIN","1");Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_FADE_SECONDS","0");var guard=alt.Prepare("action-guard");int guardFrames=(int)Math.Ceiling(guard.length*96)+1;SaveClip("Guard",guard.length,guardFrames,frame=>alt.Sample(guard.length*frame/(guardFrames-1)));
 var dance=alt.Prepare("action-67");int frames=(int)Math.Ceiling(dance.length*96)+1;Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_FADE_SECONDS","0.25");
 Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_GAIN","1");SaveClip("Dance_Original",dance.length,frames,frame=>alt.Sample(dance.length*frame/(frames-1)));
 Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_GAIN","0");SaveClip("Dance_Zero",dance.length,frames,frame=>alt.Sample(dance.length*frame/(frames-1)));
 foreach(var role in new[]{new[]{"Attack_Punch","box_02"},new[]{"Attack_Kick","front_kick_01"}}){var c=AssetDatabase.LoadAllAssetsAtPath(Root+"SailorReview.fbx").OfType<AnimationClip>().Single(v=>!v.name.StartsWith("__preview")&&v.name.EndsWith("|"+role[1]));int count=(int)Math.Ceiling(c.length*96)+1;SaveClip(role[0],c.length,count,f=>c.SampleAnimation(actor,c.length*f/(count-1)));}
 r.status="EXPORTED_PENDING_WEB_ROUNDTRIP";exit=0;
 void SaveClip(string name,float duration,int count,Action<int> sample){using(var w=new BinaryWriter(File.Create(output+"/"+name+".bin"))){for(int f=0;f<count;f++){sample(f);foreach(var t in nodes){var p=t.localPosition;var q=t.localRotation;var s=t.localScale;foreach(float v in new[]{p.x,p.y,p.z,q.x,q.y,q.z,q.w,s.x,s.y,s.z})w.Write(v);}}}var c=new Clip{name=name,file=name+".bin",duration=duration,frames=count};r.clips=(r.clips??Array.Empty<Clip>()).Concat(new[]{c}).ToArray();}
 }catch(Exception e){r.status="FAILED";r.error=e.ToString();Debug.LogException(e);}finally{alt?.Dispose();if(actor!=null)UnityEngine.Object.DestroyImmediate(actor);File.WriteAllText(output+"/export.json",JsonUtility.ToJson(r,true));EditorApplication.Exit(exit);}}
}
